mapper.select:
SELECT YEAR, MONTH, FACTORY_CODE, PRODUCT_TYPE_CODE, MONTH_PLAN_VERSION, PRODUCTION_INIT_VERSION AS INIT_VERSION, PRODUCTION_VERSION, CREATE_TIME, IS_FINAL, PRODUCTION_START_DATE, IS_NATURAL_MONTH FROM t_mp_proc_version WHERE IFNULL(IS_DELETE, 0) = 0 AND YEAR = #{year,jdbcType=DECIMAL} AND MONTH = #{month,jdbcType=DECIMAL}
AND FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
AND PRODUCT_TYPE_CODE = #{productTypeCode,jdbcType=VARCHAR}
AND MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
ORDER BY MONTH_PLAN_VERSION,PRODUCTION_VERSION

select distinct MONTH_PLAN_VERSION
from T_MP_PROC_VERSION
where IFNULL(IS_DELETE, 0) = 0
  and YEAR = #{year}
  and MONTH = #{month}
  and FACTORY_CODE = #{factoryCode}
  and MONTH_PLAN_VERSION is not null

SELECT
COUNT( DISTINCT PRODUCT_CODE ) AS skuCount,
SUM(PLAN_QTY) AS skuQty
FROM
T_MP_PRODUCT_REQUIRE_PLAN
WHERE
IS_DELETE = 0
AND `YEAR` = #{year}
AND `MONTH` = #{month}
AND FACTORY_CODE = #{factoryCode}
AND MONTH_PLAN_VERSION = #{monthPlanVersion}
AND LOCATION_TYPE = #{locationType}
AND PRODUCT_CODE = #{productCode}
AND SPECIFICATIONS = #{specifications}
AND PATTERN = #{pattern}
AND IS_ENSURE_PLAN = #{isEnsurePlan}
AND IS_STOCK_UP = #{isStockUp}
AND DELIVERY_DATE_DUE is null
AND DELIVERY_DATE_DUE is not null
